// Des: Tests for ru-page-fetc: store once, 304, dedupe, UTF-8, errors
// Flo: mock server + temp dir > run pipeline repeatedly > assert stat words, files, rows
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const pipe = @import("ru-page-fetc.zig"); const inde = @import("st-page-inde.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig"); const mock = @import("te-mock-serv.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, srv2: mock.Mock, dirz: []u8, dbzz: @import("st-stor-sqli.zig").Dbzz, aren: std.heap.ArenaAllocator, pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv2.start(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); } pub fn down(self: *Rigg) void { self.aren.deinit(); self.dbzz.close(); self.srv2.halt(); allo.free(self.dirz); self.tmpz.cleanup(); } pub fn gozz(self: *Rigg, path: []const u8) !pipe.Outc { var buf4: [64]u8 = undefined; return pipe.pageFetc(allo, self.aren.allocator(), std.testing.io, .{}, &self.dbzz, self.dirz, self.srv2.urlzOfzz(&buf4, path), true); } };
test "first fetch stores once, refetch is 304, no new file" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const one2 = try rig3.gozz("/cond"); try std.testing.expectEqualStrings("new", one2.stat); try std.testing.expectEqual(@as(u16, 200), one2.code); const two2 = try rig3.gozz("/cond"); try std.testing.expectEqualStrings("notm", two2.stat); try std.testing.expectEqual(@as(u16, 304), two2.code); try std.testing.expectEqualStrings(one2.hexz, two2.hexz); try std.testing.expectEqual(@as(i64, 2), try inde.logzCont(&rig3.dbzz)); }
test "same body without etag: second run is same, stored once" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const one2 = try rig3.gozz("/gz"); try std.testing.expectEqualStrings("new", one2.stat); const two2 = try rig3.gozz("/gz"); try std.testing.expectEqualStrings("same", two2.stat); try std.testing.expectEqualStrings(one2.hexz, two2.hexz); }
test "latin1 page is stored as UTF-8" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const one2 = try rig3.gozz("/latin"); try std.testing.expectEqualStrings("new", one2.stat); var hxzz: hash.Hexz = undefined; @memcpy(&hxzz, one2.hexz[0..64]); const rawd = try std.fs.path.join(allo, &.{ rig3.dirz, "raw" }); defer allo.free(rawd); const back = try file.fileLoad(allo, std.testing.io, rawd, hxzz, 1000); defer allo.free(back); try std.testing.expectEqualStrings("caf\xC3\xA9", back); }
test "non-2xx is logged, never stored" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const one2 = try rig3.gozz("/e403"); try std.testing.expectEqualStrings("http", one2.stat); try std.testing.expectEqual(@as(u16, 403), one2.code); try std.testing.expect(try inde.pageGetz(&rig3.dbzz, rig3.aren.allocator(), one2.urlz) == null); try std.testing.expectEqual(@as(i64, 1), try inde.logzCont(&rig3.dbzz)); }
test "errors are logged and returned typed" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try std.testing.expectError(error.NotText, rig3.gozz("/img")); try std.testing.expectError(error.RedirectLoop, rig3.gozz("/loop")); try std.testing.expectEqual(@as(i64, 2), try inde.logzCont(&rig3.dbzz)); }
test "crash after file write, before index: rerun is idempotent" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const rawd = try std.fs.path.join(allo, &.{ rig3.dirz, "raw" }); defer allo.free(rawd); const orph = try file.fileSave(allo, std.testing.io, rawd, "<html>hello</html>"); try std.testing.expect(orph.fres); const one2 = try rig3.gozz("/ok"); try std.testing.expectEqualStrings("new", one2.stat); try std.testing.expectEqualStrings(&orph.hexz, one2.hexz); const two2 = try rig3.gozz("/ok"); try std.testing.expectEqualStrings("same", two2.stat); }
